1	package com.marealata.service;
2	
3	import com.marealata.dao.*;
4	import com.marealata.model.*;
5	import com.marealata.util.*;
6	import java.math.BigDecimal;
7	import java.sql.SQLException;
8	import java.time.LocalDate;
9	import java.util.List;
10	
11	public class ReservationService {
12	    public static Reservation createReservation(int roomNumber, String guestName, String guestEmail,
13	                                                String guestCpf, LocalDate checkIn, LocalDate checkOut,
14	                                                int guests, RatePlan ratePlan) throws SQLException {
15	        validateReservation(roomNumber, checkIn, checkOut, guests);
16	
17	        Room room = RoomDao.findByNumber(roomNumber);
18	        if (room == null) {
19	            throw new ReservationException("ROOM_NOT_FOUND", "Room " + roomNumber + " not found");
20	        }
21	
22	        if (guests > room.capacity) {
23	            throw new ReservationException("CAPACITY_EXCEEDED", "Guests exceed room capacity");
24	        }
25	
26	        List<Reservation> conflicting = ReservationDao.findByRoomAndDates(roomNumber, checkIn, checkOut);
27	        if (!conflicting.isEmpty()) {
28	            throw new ReservationException("ROOM_UNAVAILABLE", "Room not available for these dates");
29	        }
30	
31	        int nights = PriceCalculator.calculateNights(checkIn, checkOut);
32	        BigDecimal subtotal = PriceCalculator.calculateSubtotal(roomNumber, checkIn, checkOut);
33	        BigDecimal discount = PriceCalculator.calculateDiscount(subtotal, ratePlan);
34	        BigDecimal total = PriceCalculator.calculateTotal(subtotal, discount);
35	
36	        Reservation reservation = new Reservation(roomNumber, guestName, guestEmail, guestCpf,
37	                                                  checkIn, checkOut, guests, ratePlan,
38	                                                  nights, subtotal, discount, total);
39	
40	        return ReservationDao.save(reservation);
41	    }
42	
43	    public static Reservation confirmReservation(long id, BigDecimal amountPaid) throws SQLException {
44	        Reservation reservation = ReservationDao.findById(id);
45	        if (reservation == null) {
46	            throw new ReservationException("RESERVATION_NOT_FOUND", "Reservation not found");
47	        }
48	
49	        if (reservation.status != ReservationStatus.PENDING) {
50	            throw new ReservationException("OPERATION_NOT_ALLOWED",
51	                "Cannot confirm a " + reservation.status + " reservation");
52	        }
53	
54	        reservation.status = ReservationStatus.CONFIRMED;
55	        reservation.amountPaid = amountPaid;
56	        ReservationDao.save(reservation);
57	
58	        Room room = RoomDao.findByNumber(reservation.roomNumber);
59	        String roomType = room != null ? room.type : "UNKNOWN";
60	
61	        MessageService.sendConfirmationEmail(reservation, roomType);
62	
63	        return reservation;
64	    }
65	
66	    public static Reservation checkIn(long id) throws SQLException {
67	        Reservation reservation = ReservationDao.findById(id);
68	        if (reservation == null) {
69	            throw new ReservationException("RESERVATION_NOT_FOUND", "Reservation not found");
70	        }
71	
72	        if (reservation.status != ReservationStatus.CONFIRMED) {
73	            throw new ReservationException("OPERATION_NOT_ALLOWED",
74	                "Cannot check in a " + reservation.status + " reservation");
75	        }
76	
77	        reservation.status = ReservationStatus.CHECKED_IN;
78	        return ReservationDao.save(reservation);
79	    }
80	
81	    public static Reservation checkOut(long id) throws SQLException {
82	        Reservation reservation = ReservationDao.findById(id);
83	        if (reservation == null) {
84	            throw new ReservationException("RESERVATION_NOT_FOUND", "Reservation not found");
85	        }
86	
87	        if (reservation.status != ReservationStatus.CHECKED_IN) {
88	            throw new ReservationException("OPERATION_NOT_ALLOWED",
89	                "Cannot check out a " + reservation.status + " reservation");
90	        }
91	
92	        reservation.status = ReservationStatus.CHECKED_OUT;
93	        return ReservationDao.save(reservation);
94	    }
95	
96	    public static Reservation cancelReservation(long id) throws SQLException {
97	        Reservation reservation = ReservationDao.findById(id);
98	        if (reservation == null) {
99	            throw new ReservationException("RESERVATION_NOT_FOUND", "Reservation not found");
100	        }
101	
102	        if (reservation.status != ReservationStatus.PENDING &&
103	            reservation.status != ReservationStatus.CONFIRMED) {
104	            throw new ReservationException("OPERATION_NOT_ALLOWED",
105	                "Cannot cancel a " + reservation.status + " reservation");
106	        }
107	
108	        reservation.status = ReservationStatus.CANCELLED;
109	
110	        if (reservation.status == ReservationStatus.CONFIRMED &&
111	            reservation.amountPaid.compareTo(BigDecimal.ZERO) > 0) {
112	            if (reservation.ratePlan == RatePlan.STANDARD) {
113	                reservation.refund = reservation.amountPaid;
114	            } else {
115	                reservation.refund = BigDecimal.ZERO;
116	            }
117	        } else {
118	            reservation.refund = BigDecimal.ZERO;
119	        }
120	
121	        return ReservationDao.save(reservation);
122	    }
123	
124	    private static void validateReservation(int roomNumber, LocalDate checkIn, LocalDate checkOut,
125	                                            int guests) {
126	        if (guests < 1) {
127	            throw new ReservationException("INVALID_REQUEST", "At least 1 guest is required");
128	        }
129	
130	        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
131	            throw new ReservationException("INVALID_REQUEST", "Check-out must be after check-in");
132	        }
133	    }
134	}
